#!/usr/bin/python3

def check_property(f, p, k):
    for i in range(p):
        if f[(k * i) % p] != (k * f[i]) % p:
            return False
    return True

def enumerate_f(f, p, k, index):
    if index == p:
        return check_property(f, p, k)
    total = 0
    for val in range(p):
        f.append(val)
        total += enumerate_f(f, p, k, index + 1)
        f.pop()
    return total

def solve(p, k):
    total_groups = 0
    visited = set()
    for j in range(p):
        if j not in visited:
            total_groups += 1
        i = j
        while i not in visited:
            visited.add(i)
            i = (i * k) % p
    return pow(p, total_groups - (k != 1), 10 ** 9 + 7)

p, k = map(int, input().split())
print(solve(p, k))
